def classify_quadratic(p, b, c):
    disc = (b * b - 4 * c) % p
    if disc == 0:
        return 'ramified'
    legendre = pow(disc, (p - 1) // 2, p)
    return 'split' if legendre == 1 else 'inert'

def enumerate_fiber(p, d):
    inv4 = pow(4, p - 2, p)
    return [(b, ((b*b - d) * inv4) % p) for b in range(p)]
